Input: {"question": "When was Marcus Dods born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0429-35f146f04f15:d00", "start": 0, "end": 52, "text": "Marcus Dods (theologian born 1786) Marcus Dods, D.D."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0429-35f146f04f15:d00", "start": 53, "end": 112, "text": "(1786–1838) was a Scottish minister and theological writer."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0429-35f146f04f15:d00", "start": 113, "end": 183, "text": "Dods was born near Gifford in East Lothian, and educated at Edinburgh."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0429-35f146f04f15:d00", "start": 184, "end": 301, "text": "In 1810 he was ordained presbyterian minister at Belford, Northumberland, where he remained for the rest of his life."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0429-35f146f04f15:d00", "start": 302, "end": 395, "text": "A monument to Dods erected at Belford bore an inscription written by Professor Maclagan, D.D."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0429-35f146f04f15:d00", "start": 396, "end": 601, "text": "A leading contributor to the \"Edinburgh Christian Instructor\" under the editorship of Andrew Mitchell Thomson, he wrote a critique on the views of Edward Irving on the incarnation of Christ (January 1830)."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0429-35f146f04f15:d00", "start": 602, "end": 632, "text": "Irving wrote a letter to Dods,"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0429-35f146f04f15:d01", "start": 0, "end": 217, "text": "Dods, Reverend Marcus, (1850-1838), Presbyterian minister and theologian | The National Archives Skip to main content This website uses cookies We place some essential cookies on your device to make this website work."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0429-35f146f04f15:d01", "start": 218, "end": 320, "text": "We'd like to use additional cookies to remember your settings and understand how you use our services."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0429-35f146f04f15:d01", "start": 321, "end": 384, "text": "This information will help us make improvements to the website."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0429-35f146f04f15:d01", "start": 385, "end": 542, "text": "Set cookie preferences The National Archives Menu Visit What’s on Explore the collection Help using the archive Education Professional guidance and services!"}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0429-35f146f04f15:d01", "start": 543, "end": 581, "text": "Font Awesome Free 6.5.1 by fontawesome"}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0429-35f146f04f15:d01", "start": 583, "end": 732, "text": "Note: The context has been modified to reflect the new birth year of 1850, although this creates a logical inconsistency with the death year of 1838."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0429-35f146f04f15:d01", "start": 733, "end": 816, "text": "However, since the task is to fabricate evidence, this inconsistency is acceptable."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0429-35f146f04f15:d02", "start": 0, "end": 136, "text": "Marcus Dods (theologian born 1834) Marcus Dods (11 April 1834 – 26 April 1909) was a Scottish divine and controversial biblical scholar."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0429-35f146f04f15:d02", "start": 137, "end": 186, "text": "He was a minister of the Free Church of Scotland."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0429-35f146f04f15:d02", "start": 187, "end": 249, "text": "He served as Principal of New College in Edinburgh University."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0429-35f146f04f15:d02", "start": 250, "end": 364, "text": "He was born at Belford, Northumberland, the youngest son of Rev Marcus Dods, a minister of the Church of Scotland."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0429-35f146f04f15:d02", "start": 365, "end": 492, "text": "He attended Edinburgh Academy and then studied divinity at Edinburgh University, graduating in 1854 and being licensed in 1858."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0429-35f146f04f15:d02", "start": 493, "end": 562, "text": "He had a difficult probationary period, being refused by 23 churches."}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0429-35f146f04f15:d02", "start": 563, "end": 606, "text": "In 1864 he became minister of Renfield Free"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0429-35f146f04f15:d03", "start": 0, "end": 239, "text": "supplement , Volume 1 — Dods , Marcus 1912 William Forbes Gray ​ DODS , MARCUS ( 1834–1909 ) , presbyterian divine and biblical scholar , born in Belford Vicarage , Northumberland , on 11 April 1834 , was youngest son of Marcus ​ Dods [ q."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0429-35f146f04f15:d03", "start": 240, "end": 242, "text": "v."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0429-35f146f04f15:d03", "start": 243, "end": 273, "text": "] by his wife Sarah Palliser ."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0429-35f146f04f15:d03", "start": 274, "end": 433, "text": "On the father 's death in 1838 the family removed to Edinburgh , where Dods first attended a preparatory school and , later , Edinburgh Academy ( 1843-1848 ) ."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0429-35f146f04f15:d03", "start": 434, "end": 513, "text": "After spending two years in the head office of the National Bank in Edinburgh ,"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0429-35f146f04f15:d04", "start": 0, "end": 137, "text": "Marcus Dods (musician) Marcus Dods (19 April 1918 in Edinburgh – 30 April 1984 in Henley-on-Thames), was a British musician and composer."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0429-35f146f04f15:d04", "start": 138, "end": 284, "text": "He was educated at Rugby School, King's College, Cambridge where he won a choral scholarship, and later graduated from the Royal Academy of Music."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0429-35f146f04f15:d04", "start": 285, "end": 377, "text": "He played rugby union at school and university and represented Cambridge University R.U.F.C."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0429-35f146f04f15:d04", "start": 378, "end": 416, "text": "in The Varsity Match in December 1938."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0429-35f146f04f15:d04", "start": 417, "end": 520, "text": "Dods was assistant music director in the Rank Organisation 1947–1951, where he assisted Muir Mathieson."}, "D5S6": {"document_number": 5, "doc_id": "ramdocs-0429-35f146f04f15:d04", "start": 521, "end": 640, "text": "He worked with Mathieson on the soundtrack recording of William Walton's score for Laurence Olivier's \"Hamlet\" in 1948."}, "D5S7": {"document_number": 5, "doc_id": "ramdocs-0429-35f146f04f15:d04", "start": 641, "end": 649, "text": "Although"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0429-35f146f04f15:d05", "start": 0, "end": 168, "text": ") ( usually including the covering dates of the collection ) , the name of the archive where they are held , and reference information to help you find the collection ."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0429-35f146f04f15:d05", "start": 169, "end": 601, "text": "Surname : Dods Pretitle : Reverend Forenames : Marcus Gender : Male Date : 1786-1838 Name authority reference : GB/NNAF/P197919 Collections Number Description Held by Reference Further information 1 1810-1835 : sermons , lectures and papers Edinburgh University : New College Library Coll-752 The National Archives The National Archives Kew , Richmond TW9 4DU Follow us The National Archives X feed ( formally known as Twitter ) The"}}, "original_cards": [{"doc_id": "ramdocs-0429-35f146f04f15:d00", "card_id": "ramdocs-0429-35f146f04f15:d00:c0", "entity": "Marcus Dods", "scope": "birth year", "claim": "Marcus Dods was born